import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Docker Compose","description":"拷贝 deploy/ 目录，改一份 .env，即可一键拉起官方镜像 + PostgreSQL + Redis。","frontmatter":{"title":"Docker Compose","description":"拷贝 deploy/ 目录，改一份 .env，即可一键拉起官方镜像 + PostgreSQL + Redis。"},"headers":[],"relativePath":"guide/install/compose.md","filePath":"guide/install/compose.md","lastUpdated":1790057721000}`),a={name:`guide/install/compose.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="docker-compose" tabindex="-1">Docker Compose <a class="header-anchor" href="#docker-compose" aria-label="Permalink to “Docker Compose”">​</a></h1><p><a href="https://github.com/Kirizu-Official/KiriVers/tree/main/deploy" target="_blank" rel="noreferrer"><code>deploy/</code></a> 是给使用者的一键目录：官方镜像 + PostgreSQL + Redis。整目录可以拷到服务器，不必再从仓库其它位置抄配置。</p><div class="info custom-block"><p class="custom-block-title">不要和开发文件搞混</p><p><code>dev/docker/compose.yml</code> 只给本机 <code>go run .</code> 起 Postgres/Redis，<strong>不含</strong> KiriVers 进程。仓库里给使用者的一键栈只有 <code>deploy/</code> 这一份（<code>dev/build/</code> 不再放 Compose 文件，只有运行镜像 <code>Dockerfile</code> 与发版 CLI）。</p></div><h2 id="启动" tabindex="-1">启动 <a class="header-anchor" href="#启动" aria-label="Permalink to “启动”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 改 POSTGRES_PASSWORD、REDIS_PASSWORD、URL_SIGNING_SECRET</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>.env</code> 是唯一口令入口。同一组值会同时进入：</p><table tabindex="0"><thead><tr><th>写在 <code>.env</code></th><th>用到哪里</th></tr></thead><tbody><tr><td><code>POSTGRES_*</code></td><td>PostgreSQL 容器，以及进程的 <code>KIRIVERS_POSTGRES_DSN</code></td></tr><tr><td><code>REDIS_PASSWORD</code></td><td>Redis <code>requirepass</code>，以及 <code>KIRIVERS_CACHE_REDIS_PASSWORD</code></td></tr><tr><td><code>URL_SIGNING_SECRET</code></td><td><code>KIRIVERS_URL_SIGNING_SECRET</code></td></tr></tbody></table><p><code>deploy/config/</code> 里已有三份 YAML，<strong>不要</strong>再从 <code>configs/*-example.yaml</code> 复制。YAML 里的 <code>CHANGE_ME</code> 会被 <code>.env</code> 覆盖，改 YAML 里的库口令不会生效。</p><p>进程固定 <code>KIRIVERS_CACHE_DRIVER=redis</code>，地址 <code>redis:6379</code>。预期：<code>docker compose ps</code> 中 <code>postgres</code>、<code>redis</code>、<code>kirivers</code> 均为 running。浏览器打开 <code>http://127.0.0.1:8081</code>。</p><p>数据在 <code>deploy/data/</code>（Postgres、Redis AOF、安装包、日志）。对外只映射 <code>8080</code> / <code>8081</code>。</p><div class="danger custom-block"><p class="custom-block-title">示例口令</p><p><code>.env.example</code> 里的 <code>CHANGE_ME</code> 不能用于生产。</p></div><h2 id="用哪个镜像标签" tabindex="-1">用哪个镜像标签 <a class="header-anchor" href="#用哪个镜像标签" aria-label="Permalink to “用哪个镜像标签”">​</a></h2><p><code>deploy/compose.yml</code> 里写的是 <code>kirizuofficial/kirivers:latest</code>，即<strong>最近一次发版</strong>。想固定在某个版本，把 <code>image:</code> 改成对应标签：</p><table tabindex="0"><thead><tr><th>标签</th><th>含义</th></tr></thead><tbody><tr><td><code>kirizuofficial/kirivers:latest</code></td><td>最近一次发版</td></tr><tr><td><code>kirizuofficial/kirivers:&lt;semver&gt;</code></td><td>指定版本的多架构 manifest（按宿主架构自动选）</td></tr><tr><td><code>kirizuofficial/kirivers:&lt;semver&gt;_amd64</code> / <code>&lt;semver&gt;_arm64</code></td><td>该版本的单架构镜像，只在明确锁定架构时用</td></tr></tbody></table><p>官方镜像只有 <code>linux/amd64</code> 与 <code>linux/arm64</code> 两种（Alpine 基底、musl 构建）。其他 Linux 架构没有镜像，请改用 <a href="/guide/install/manual">Releases 的 zip 包</a>。升级前先备份 PostgreSQL 与 <code>storage.local.root</code>，再 <code>docker compose pull &amp;&amp; docker compose up -d</code>。</p><p>下一步：<a href="/guide/config/bootstrap-admin">管理员初始化</a>。</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};